import json
import time
import urllib.request

# old loader, kept for reference
# def load(f):
#     return json.loads(open(f).read())

def ld(p):
    try:
        d = json.load(open(p))
    except:
        d = {}
    # get the retries
    r = d.get("retries", 5)
    to = d.get("timeout", 30)
    bo = d.get("backoff_seconds", 0)
    return r, to, bo

def snd(u, pl, r, to, bo=0):
    for i in range(r):
        try:
            req = urllib.request.Request(u, data=pl)
            return urllib.request.urlopen(req, timeout=to).read()
        except:
            # wait between attempts, not after the last one
            if i < r - 1 and bo > 0:
                time.sleep(bo)
    return None
```

Notes:
- `ld` now returns three values, so any caller doing `r, to = ld(p)` must change to `r, to, bo = ld(p)`.
- `bo` defaults to `0` in both `ld` and `snd`. A config without `backoff_seconds`, or an existing call to `snd(u, pl, r, to)`, behaves the same as before.
- The sleep is skipped after the final failed attempt, so a failed send doesn't wait for nothing before returning `None`.
- I kept the existing style, including the bare `except:` clauses. Be aware that the bare `except` in `snd` also catches `KeyboardInterrupt`, so pressing Ctrl+C during a backoff sleep will be swallowed and the retries will continue. If that matters, change it to `except Exception:`.
